package com.arnavgames.tycoon.core.content

import kotlinx.serialization.Serializable

/** Real-estate content (content/data/estates.json, generated by tools/content/gen_estates.py). docs/GDD.md §7. */
@Serializable
data class EstateContent(
    val config: EstateConfig,
    val cities: List<CityDef>,
    val districts: List<DistrictDef>,
    val types: List<PropertyTypeDef>,
    val towers: List<TowerDef>,
    val events: List<TenantEventDef>,
) {
    @kotlinx.serialization.Transient val cityById: Map<String, CityDef> = cities.associateBy { it.id }
    @kotlinx.serialization.Transient val districtById: Map<String, DistrictDef> = districts.associateBy { it.id }
    @kotlinx.serialization.Transient val typeById: Map<String, PropertyTypeDef> = types.associateBy { it.id }
    @kotlinx.serialization.Transient val towerById: Map<String, TowerDef> = towers.associateBy { it.id }
    @kotlinx.serialization.Transient val eventById: Map<String, TenantEventDef> = events.associateBy { it.id }

    companion object {
        val EMPTY = EstateContent(EstateConfig(), emptyList(), emptyList(), emptyList(), emptyList(), emptyList())
    }
}

@Serializable
data class EstateConfig(
    val transactionCost: Double = 0.03,
    val propertyTaxPerDay: Double = 0.002,
    val insurancePerDay: Double = 0.0005,
    val mortgageSpreadPerDay: Double = 0.003,
    val mortgageLtvOptions: List<Double> = listOf(0.0, 0.5, 0.6),
    val foreclosureLtv: Double = 0.95,
    val listingRefreshHours: Int = 6,
    val listingsMin: Int = 3,
    val listingsMax: Int = 5,
    val distressedChance: Double = 0.25,
    val distressedDiscountMin: Double = 0.70,
    val distressedDiscountMax: Double = 0.85,
    val disasterChancePer6h: Double = 0.004,
    val eventChancePer6h: Double = 0.03,
    val maxQueuedEvents: Int = 3,
    val unresolvedRentFactor: Double = 0.8,
    val gentrificationChancePerDay: Double = 0.03,
    val gentrificationBoost: Double = 0.08,
    val repairCost: Double = 0.06,
    val repairHours: Int = 2,
    val maxRenovations: Int = 3,
    val maxProperties: Int = 40,
    /** Upkeep factor of a business that operates from the player's own property (it pays no rent). */
    val hostedUpkeepFactor: Double = 0.9,
    val towerConstructionDiscount: Double = 0.8,
    val unlocks: Map<String, Int> = mapOf("estates" to 2, "mortgages" to 3, "skyscrapers" to 5),
    /** Extra price-index swing by macro phase. */
    val macroAmplitude: Map<String, Double> = emptyMap(),
)

@Serializable
data class CityDef(
    val id: String,
    val name: String,
    val chapter: Int,
    /** Position on the app's world map (0..1, from longitude/latitude). */
    val x: Double,
    val y: Double,
    val longitude: Double = 0.0,
    val latitude: Double = 0.0,
    val description: String,
    /** Multiplier on every property price in the city (pegged to the business price ladder). */
    val priceScale: String,
    val periodDays: Double,
    val amplitude: Double,
    val phase: Double,
)

@Serializable
data class DistrictDef(
    val id: String,
    val city: String,
    val name: String,
    val tier: Double,
    val yieldPerDay: Double,
    val cbd: Boolean,
    val risk: Double,
    val types: List<String>,
    val periodDays: Double,
    val amplitude: Double,
    val phase: Double,
    val trendPerDay: Double,
    val x: Double,
    val y: Double,
)

@Serializable
data class PropertyTypeDef(
    val id: String,
    val name: String,
    val icon: String,
    val basePrice: Dollars,
    val yieldMultiplier: Double,
    val renovationCost: Double,
    val renovationHours: Int,
    val renovationValue: Double,
    val renovationRent: Double,
    val saleHours: Int,
    val risk: Double,
    /** Businesses that can operate from this property type. */
    val hosts: List<String>,
)

@Serializable
data class TowerDef(
    val id: String,
    val name: String,
    val floors: Int,
    val stageCosts: List<Dollars>,
    val stageHours: List<Int>,
    val stageNames: List<String>,
    val value: Dollars,
    val floorRentPerDay: Double,
    val landmarkBoost: Double,
)

@Serializable
data class TenantEventDef(val id: String, val text: String, val choices: List<TenantChoiceDef>)

@Serializable
data class TenantChoiceDef(
    val label: String,
    /** Cost or gain in multiples of one 6-hour market rent. */
    val costRent: Double = 0.0,
    val gainRent: Double = 0.0,
    /** Change in condition, permille. */
    val condition: Int = 0,
    /** The tenant leaves; a new one moves in after this many hours. */
    val vacancyHours: Int = 0,
    /** Rent +10 % for this many days (negative: −10 %). */
    val boostDays: Double = 0.0,
)
